#!/usr/bin/env sh
# Creates .env for docker compose with fresh random secrets. Safe to run once; won't overwrite.
set -eu
cd "$(dirname "$0")/.."
if [ -f .env ]; then
  echo ".env already exists. Delete it first if you really want new secrets (existing files would become unreadable)." >&2
  exit 1
fi
command -v openssl >/dev/null || { echo "openssl is needed to generate secrets." >&2; exit 1; }
umask 077
cat > .env <<ENV
# Generated by scripts/init-env.sh. Keep this file private and backed up:
# losing MASTER_KEY means losing every stored file.
WEB_ORIGIN=http://localhost:8020
POSTGRES_PASSWORD=$(openssl rand -hex 24)
JWT_SECRET=$(openssl rand -base64 48 | tr -d '\n')
CODE_PEPPER=$(openssl rand -base64 32 | tr -d '\n')
KEY_DRIVER=env
MASTER_KEY=$(openssl rand -base64 32 | tr -d '\n')
STORAGE_DRIVER=local
MAX_UPLOAD_MB=20
COMPOSE_PROFILES=clamav
CLAMAV_ENABLED=true
MAIL_DRIVER=file
# MAIL_DRIVER=smtp
# SMTP_URL=smtps://user:password@smtp.example.com:465
# MAIL_FROM=Your Business <documents@example.com>
SIGNUP_ENABLED=true
DEMO_MODE=false
ENV
echo "Wrote .env with new secrets. Next: docker compose up -d, then open http://localhost:8020"
